def correct_bracketing(brackets: str) -> bool:
    """Return True if every opening bracket '<' has a corresponding closing bracket '>'.
    The string may contain only '<' and '>'.
    """
    balance = 0
    for ch in brackets:
        if ch == '<':
            balance += 1
        elif ch == '>':
            balance -= 1
        # If we have more closing than opening at any point, it's invalid.
        if balance < 0:
            return False
    # All brackets are matched only if the final balance is zero.
    return balance == 0

