def get_row(lst, x):
    """
    Returns a list of (row, column) indices for all occurrences of x in lst.
    The list is sorted first by row in ascending order, then by column in descending order.
    """
    coordinates = []
    for row_index, row in enumerate(lst):
        for col_index, value in enumerate(row):
            if value == x:
                coordinates.append((row_index, col_index))
    # Sort by row ascending, then column descending
    coordinates.sort(key=lambda t: (t[0], -t[1]))
    return coordinates

