def words_in_sentence(sentence: str) -> str:
    """
    Returns a string containing only those words from the input sentence
    whose lengths are prime numbers, preserving the original order.
    """
    def is_prime(n: int) -> bool:
        """Return True if n is a prime number, False otherwise."""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        # Check odd divisors up to sqrt(n)
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # Split the sentence into words (default splits on any whitespace)
    words = sentence.split()
    # Keep only words with prime length
    result = [word for word in words if is_prime(len(word))]
    # Join them back with spaces
    return " ".join(result)

