def bf(planet1, planet2):
    # List of planets in order from the Sun
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check if both planet names are valid
    if planet1 not in planets or planet2 not in planets:
        return ()

    # Get indices
    i1 = planets.index(planet1)
    i2 = planets.index(planet2)

    # Determine the range between them (exclusive of endpoints)
    start = min(i1, i2) + 1
    end = max(i1, i2) - 1

    # Return the planets in that range, sorted by proximity to the Sun
    if start <= end:
        return tuple(planets[start:end+1])
    else:
        return ()
